/**
 * USMCA Machinery, Electrical and Electronic Equipment Rules of Origin —
 * HS Chapters 84-85 pass, unified-schema sector file for OrigynLX.
 * Modeled on the automotive sector file (AUTOMOTIVE_SECTOR_FILE) template
 * (explicit object-literal records — no generator functions).
 * REVISION 3 — STRUCTURAL REBUILD ON THE TEMPLATE. Rev. 2 carried all the
 * verbatim GN 11 content but deviated structurally from the automotive/
 * optics record pattern (generator functions mk/ab/nc/chapNote, threshold
 * field naming, rule-number ids, no rules field in the sector file). Rev. 3
 * keeps the rev. 2 verbatim content — transcribed VERBATIM from HTSUS
 * General Note 11 (2026 Revision 15), subdivision (o), as supplied in the
 * official USITC PDF (Chapter 84: GN pp. 69-96; Chapter 85: GN pp. 96-110)
 * — and restores the template exactly.
 *
 * CHAPTERS COVERED BY THIS FILE (for the calculator's chapter routing):
 *   84 Nuclear reactors, boilers, machinery and mechanical appliances; parts
 *   85 Electrical machinery and equipment and parts; sound/TV equipment
 *
 * WHAT IS IN THIS PASS (393 records):
 *  - Chapter 84 (261 records): chapter rules 1-7 (PCA definition, unit-origin
 *    rules for 8471.49, printer/fax/photocopier parts lists, GN 11(k)
 *    underscore routing) PLUS numbered rules 1-254, including the VEHICLE-USE
 *    splits: 8407.31-.34 (passenger/light-truck 75 NC, heavy truck 70 NC,
 *    other 60/50), 8408.20 (light truck 85/75 no-change, heavy truck 80/70
 *    shift-AND, other 60/50), 8409.91/.99 (75 NC / 70 NC / 60/50), 8481.40-.80
 *    (UNIQUE 45/35), and the 8459.x machine-tool family with the unusual
 *    (A)/(B)/(C) structure where (C) supplies the RVC tail of branch (B).
 *  - Chapter 85 (132 records): chapter rules 1-6 (PCA definition, unit-origin
 *    rule for 8471.49, 'front panel assembly' definition, GN 11(k) routing)
 *    PLUS numbered rules 1-120, including the TIME-BASED 8504 transformer
 *    windows (2020-07-01 until 2025-07-01: 60/50 RVC; from 2025-07-01:
 *    65/55 + steel exception headings 7225/7226/7326 — the 2025 rules are
 *    NOW IN FORCE), the 8540.12 glass-panel/glass-envelope blocks, 8507.60
 *    EV propulsion batteries (branch (B) 85/75 no-change; branch (D) 60/50),
 *    no-change-only Article 4.18 rules (8523.52 smart cards, 8541-8542,
 *    8543.90, 8548.90), and unique thresholds 30/25 (8518.90), 40/30
 *    (8529.90), 50/40 (8537).
 *  - RVC-option census: 311 options across 157 phase-bearing records
 *    (135 records use the shared RVC_60_50 / RVC_NOSIFT_60_50 constants;
 *    22 records carry inline branch-specific options).
 *
 * REV. 2 -> REV. 3 CORRECTIONS (flagged for audit):
 *  - Seven rev. 2 records mis-passed an audit note into the ab() except slot,
 *    which would have injected '... except from PRINT ODDITY: ...' into the
 *    rule text. Corrected here so the note lands in notes and no except
 *    clause is fabricated: 8403.10, 8451.10, 8455.30, 8478.10, 8481.10-30,
 *    8483.10, 8504.50.
 *
 * OCR/PRINT ODDITIES TRANSCRIBED AS PRINTED (flagged for audit):
 *  - Rule 196 (8468): the printed RVC block shows only '2) 50 percent where
 *    the net cost method is used.' — the 60-percent transaction-value clause
 *    is missing from the print; 60/50 presumed from the pattern.
 *  - Rule 113 (8543.90): the (2) net-cost clause prints BEFORE the (1)
 *    transaction-value clause — reversed order; branch (A) also prints
 *    'No change in tariff classification electronic microassemblies'
 *    (missing 'to').
 *  - 'heading 84.31' (rule 84); 8409.91 cited inside the 8409.99 rules
 *    30/31; plural 'subheadings' before single subheadings (rules 5, 125,
 *    138, 233, 248, ch. 85 rule 8); 'toner receptable unit' and 'charge
 *    couples device' (ch. 84 chapter rules 3/4); 'thatgroup' (rule 99);
 *    '(f) or combinations' (ch. 84 chapter rule 5); 'used, or' comma
 *    (rules 142, ch. 85 rule 18); missing 'is used' (rule 135); 'provided
 *    there is also a regional value content' (ch. 85 rule 31); stray 'or,'
 *    (ch. 85 rule 89); 'A change of subheading 8529.90' (ch. 85 rule 66);
 *    'reviewing screen' (ch. 85 chapter rule 2); ch. 84 chapter rule 2
 *    prints 'the rate that is applicable' where ch. 85's parallel chapter
 *    rule 6 prints 'the rule that would be applicable'.
 *
 * OVERLAP RULE (do not create two-files-two-numbers bugs):
 *  - De minimis (GN 11(e), 10 percent) is OWNED by the core types file.
 *  - GN 11(b)(iv) fallback (60 TV / 50 NC) is OWNED by the core types file.
 *  - GN 11(k) automotive thresholds are OWNED by the automotive file;
 *    here only the chapter 84/85 motor-vehicle-use flags and thresholds
 *    are recorded (K_NOTE annotations per rule).
 *  - Steel headings 7225/7226/7326 (ch. 72/73) are OWNED by the base-metals
 *    file; here they appear only as time-based-rule exceptions.
 *  - Chapters 86-89 (transport), 90-92 (optics) and 93+ rules (own files)
 *    are not restated here.
 */
import type { UsmcaRule, UsmcaSectorFile, UsmcaSource } from "../usmca-rule-types";

const HTS_GN11_2026: UsmcaSource = {
  authority: "USITC",
  title: "Harmonized Tariff Schedule of the United States (2026) Revision 15 — General Note 11, United States-Mexico-Canada Agreement, subdivision (o) (Chapters 84-85 product-specific rules of origin tables)",
  url: "https://hts.usitc.gov/download",
  reference: "GN 11(o) Ch. 84 (pp. 69-96), Ch. 85 (pp. 96-110)",
};

const USTR_CH4_TEXT: UsmcaSource = {
  authority: "USTR",
  title: "USMCA Chapter 4 (Rules of Origin) legal text, incl. Annex 4-B (Product-Specific Rules of Origin), Chapters 84-85",
  url: "https://ustr.gov/sites/default/files/files/agreements/FTA/USMCA/Text/04-Rules-of-Origin.pdf",
  reference: "Annex 4-B Chapters 84-85 — treaty source of the same rules",
};

const GAC_CUSMA_CH4: UsmcaSource = {
  authority: "Global Affairs Canada",
  title: "CUSMA Chapter 4 — Rules of Origin (consolidated official text)",
  url: "https://www.international.gc.ca/trade-commerce/trade-agreements-accords-commerciaux/agr-acc/cusma-aceum/text-texte/04.aspx?lang=eng",
  reference: "Annex 4-B Chapters 84-85 rules (corroborating official text)",
};

const SRC = [HTS_GN11_2026, USTR_CH4_TEXT, GAC_CUSMA_CH4];

const RVC_60_50 = [
  { method: "transaction-value" as const, thresholdPercent: 60, condition: "Alternative branch: qualifying change named in the rule, whether or not there is also a change from any other heading/chapter — RVC not less than 60 percent by transaction value" },
  { method: "net-cost" as const, thresholdPercent: 50, condition: "Alternative branch: qualifying change named in the rule, whether or not there is also a change from any other heading/chapter — RVC not less than 50 percent by net cost" },
];

const RVC_NOSIFT_60_50 = [
  { method: "transaction-value" as const, thresholdPercent: 60, condition: "No change in tariff classification to the good — RVC not less than 60 percent by transaction value" },
  { method: "net-cost" as const, thresholdPercent: 50, condition: "No change in tariff classification to the good — RVC not less than 50 percent by net cost" },
];

