    ruleBasis: "special",
    tariffShiftRule: "Chapter Rule 3: Tariff items 8529.90.83, 8529.90.93 and 8529.90.99 cover the following parts of television receivers, video monitors, and video projectors: (a) Video intermediate (IF) amplifying and detecting systems; (b) Video processing and amplification systems; (c) Synchronizing and deflection circuitry; (d) Tuners and tuner control systems; and (e) Audio detection and amplification systems.",
